graphql.query:
query clientAsset ($clientId: ID!, $id: ID!) {
    clientAsset (clientId: $clientId, id: $id) {
        client {
            id
            name
        }
        created
        description
        findings {
            id
            instances {
                report_flaw_title
                report_id
                report_severity
                report_status
            }
            severity
            status
            title
        }
        id
        name
    }
}

mutation FindingUpdate($clientId: Int!, $data: FindingUpdateInput!, $findingId: Float!, $reportId: Int!) {
  findingUpdate(
    clientId: $clientId
    data: $data
    findingId: $findingId
    reportId: $reportId
  ) {
    ... on FindingUpdateSuccess {
      finding {
        ...FindingFragment
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment FindingFragment on Finding {
  assignedTo
  closedAt
  createdAt
  code_samples {
    caption
    code
    id
    __typename
  }
  common_identifiers {
    CVE {
      name
      id
      year
      link
      __typename
    }
    CWE {
      name
      id
      link
      __typename
    }
    __typename
  }
  description
  exhibits {
    assets {
      asset
      id
      __typename
    }
    caption
    exhibitID
    index
    type
    __typename
  }
  fields {
    key
    label
    value
    __typename
  }
  flaw_id
  includeEvidence
  recommendations
  references
  scores
  selectedScore
  severity
  source
  status
  subStatus
  tags
  title
  visibility
  calculated_severity
  risk_score {
    CVSS3_1 {
      overall
      vector
      subScore {
        base
        temporal
        environmental
        __typename
      }
      __typename
    }
    CVSS3 {
      overall
      vector
      subScore {
        base
        temporal
        environmental
        __typename
      }
      __typename
    }
    CVSS2 {
      overall
      vector
      subScore {
        base
        temporal
        __typename
      }
      __typename
    }
    CWSS {
      overall
      vector
      subScore {
        base
        environmental
        attackSurface
        __typename
      }
      __typename
    }
    __typename
  }
  hackerOneData {
    bountyAmount
    programId
    programName
    remoteId
    __typename
  }
  snykData {
    issueType
    pkgName
    issueUrl
    identifiers {
      CVE
      CWE
      __typename
    }
    exploitMaturity
    patches
    nearestFixedInVersion
    isMaliciousPackage
    violatedPolicyPublicId
    introducedThrough
    fixInfo {
      isUpgradable
      isPinnable
      isPatchable
      isFixable
      isPartiallyFixable
      nearestFixedInVersion
      __typename
    }
    __typename
  }
  edgescanData {
    id
    portal_url
    details {
      html
      id
      orginal_detail_hash
      parameter_name
      parameter_type
      port
      protocol
      screenshot_urls {
        file
        id
        medium_thumb
        small_thumb
        __typename
      }
      src
      type
      __typename
    }
    __typename
  }
  __typename
}

mutation NarrativeUpdate($clientId: Int!, $data: [NarrativeInput!]!, $reportId: Int!, $tenantId: Int!) {
  narrativeUpdate(
    clientId: $clientId
    data: $data
    reportId: $reportId
    tenantId: $tenantId
  ) {
    ...NarrativeFragment
    __typename
  }
}

fragment NarrativeFragment on Narrative {
  id
  label
  tags
  text
  titleCommentThreadId
  isFromNarrativesDB
  __typename
}

